import{_ as e,o as s,c as i,a2 as t}from"./chunks/framework.yo2CxoV2.js";const k=JSON.parse('{"title":"部署与升级","description":"","frontmatter":{},"headers":[],"relativePath":"development/deployment.md","filePath":"development/deployment.md","lastUpdated":1794440372000}'),o={name:"development/deployment.md"};function n(l,a,d,h,p,r){return s(),i("div",null,[...a[0]||(a[0]=[t(`<h1 id="部署与升级" tabindex="-1">部署与升级 <a class="header-anchor" href="#部署与升级" aria-label="Permalink to &quot;部署与升级&quot;">​</a></h1><h2 id="普通-django-部署" tabindex="-1">普通 Django 部署 <a class="header-anchor" href="#普通-django-部署" aria-label="Permalink to &quot;普通 Django 部署&quot;">​</a></h2><p>发行包已包含前端构建产物。安装或升级依赖后，在项目环境执行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> manage.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> migrate</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> manage.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> collectstatic</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --noinput</span></span></code></pre></div><p>按项目原有流程重启应用服务，并检查 <code>/admin/api/health/</code>；如果挂载点不是 <code>/admin/</code>，相应调整地址。</p><p>使用 <code>ordloom==1.1.0</code>，迁移应用标签与权限前缀为 <code>ordloom</code>，应用表使用 <code>ordloom_*</code>。接入步骤见 <a href="./../getting-started/installation.html">安装说明</a>。</p><p>分享密码限速默认开启，多 Web/命令进程需使用同一具备原子计数的默认共享缓存。后台任务运行诊断默认关闭，启用后只观测显式 <code>--apply</code>，宿主仍负责 cron/任务平台调度。 配置、默认额度与只读权限见 <a href="./../guides/sharing-and-task-diagnostics.html">专项指南</a>。缓存历史不等同实时进程心跳或持久审计。</p><h2 id="静态资源" tabindex="-1">静态资源 <a class="header-anchor" href="#静态资源" aria-label="Permalink to &quot;静态资源&quot;">​</a></h2><p>发布时同时部署入口和全部内容 hash 资源，不要只覆盖 <code>index.js</code>。工作台、列表、地图、编辑器及 Worker 都可能按需加载。</p><p>入口 HTML 使用重新验证缓存策略，固定入口通过版本参数区分；内容 hash 文件可以采用长期缓存。CDN、代理或对象存储配置应保留正确路径和 MIME 类型。</p><p>旧缓存导致界面仍是旧版本时，先确认服务端包版本、<code>collectstatic</code> 结果以及实际加载的资源路径。</p><h2 id="媒体与存储" tabindex="-1">媒体与存储 <a class="header-anchor" href="#媒体与存储" aria-label="Permalink to &quot;媒体与存储&quot;">​</a></h2><p><code>MEDIA_URL</code> 与实际 storage URL 前缀应一致。生产文件由媒体服务、对象存储或项目网关提供；Django 示例中的 <code>static(settings.MEDIA_URL, ...)</code> 仅用于开发环境。</p><p>自定义 storage 应能通过 <code>storage.url(&quot;&quot;)</code> 或项目 <code>MEDIA_URL</code> 识别自身地址。跨域文件还要考虑浏览器图片、视频和下载所需的访问配置。</p><h2 id="csp-与-worker" tabindex="-1">CSP 与 Worker <a class="header-anchor" href="#csp-与-worker" aria-label="Permalink to &quot;CSP 与 Worker&quot;">​</a></h2><p>Markdown 解析使用 Worker。同源静态部署应允许对应 Worker；跨域静态托管通常还需要静态服务 CORS、脚本来源和 <code>worker-src blob:</code>。</p><p>按自己部署域名编写精确来源规则。不要为了消除一个资源错误就全局关闭 CSP 或 CSRF。</p><h2 id="修改前端源码后" tabindex="-1">修改前端源码后 <a class="header-anchor" href="#修改前端源码后" aria-label="Permalink to &quot;修改前端源码后&quot;">​</a></h2><p>在配套源码仓库中：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> frontend</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ci</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span></code></pre></div><p>项目提供 <code>scripts/sync-dist.sh</code> 将构建产物同步到 Django 包。构建 Python 发行包前应先同步，并从干净的构建目录打包，避免旧的 hash 文件混入产物。</p><h2 id="升级验证" tabindex="-1">升级验证 <a class="header-anchor" href="#升级验证" aria-label="Permalink to &quot;升级验证&quot;">​</a></h2><p>验证登录、核心模型读取和保存、关联明细、上传、用户权限、密码策略、CSV 和懒加载编辑器。检查浏览器是否出现脚本、资源路径或 Worker 错误。</p><p>发行包兼容标识与当前品牌状态见<a href="./../reference/compatibility.html">版本与兼容</a>。</p><h2 id="_1-0-2-的通知与发布保障" tabindex="-1">1.0.2 的通知与发布保障 <a class="header-anchor" href="#_1-0-2-的通知与发布保障" aria-label="Permalink to &quot;1.0.2 的通知与发布保障&quot;">​</a></h2><p>已有公开通知设置可以继续使用；本版没有新增数据库迁移。临时故障会重新取票鉴权，配置变化会重载页面，真正撤权仍清除数据。多个组件共用 3 路读取队列与公开预算，Redis 应显式配置连接和读取超时，见 <a href="./../guides/resilience-and-release-gates.html">恢复与调度指南</a>。</p><p>源码 Release 仍只接受手动触发，回归、跨进程服务、长期证据、安装迁移与打包检查失败都会阻止发布。独占服务运行器不接受既有数据库或缓存；90 秒故障冒烟不替代至少 30 分钟持续运行证据。生产代理、实际设备和目标负载应另行验收。</p>`,27)])])}const g=e(o,[["render",n]]);export{k as __pageData,g as default};
